264	            }
265	        }
266	
267	        BigDecimal installmentAmount = PricingUtil.divide(finalTotal, new BigDecimal(inst));
268	
269	        return new PaymentAdjustmentInfo(finalTotal, adjustment, inst, installmentAmount);
270	    }
271	
272	    private BigDecimal calculateInstallmentMultiplier(BigDecimal monthlyRate, Integer installments) {
273	        BigDecimal numerator = monthlyRate;
274	        BigDecimal denominator = BigDecimal.ONE;
275	        BigDecimal monthlyRatePlus1 = monthlyRate.add(BigDecimal.ONE);
276	
277	        BigDecimal power = monthlyRatePlus1.pow(installments);
278	        denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(power, 10, java.math.RoundingMode.HALF_EVEN));
279	
280	        return numerator.divide(denominator, 10, java.math.RoundingMode.HALF_EVEN);
281	    }
282	
283	    private BigDecimal calculateNextPurchaseCredit(ClubTier tier, BigDecimal subtotal) {
284	        if (tier == ClubTier.SILVER) {
285	            return PricingUtil.percentage(subtotal, new BigDecimal("2"));
286	        } else if (tier == ClubTier.GOLD) {
287	            return PricingUtil.percentage(subtotal, new BigDecimal("5"));
288	        }
289	        return BigDecimal.ZERO;
290	    }
291	
292	    private Boolean shouldGiveGift(ClubTier tier, BigDecimal subtotal) {
293	        if (tier == ClubTier.GOLD && subtotal.compareTo(new BigDecimal("500")) > 0) {
294	            return true;
295	        }
296	        return false;
297	    }
298	}
299	package com.loja.orderservice.util;
300	
301	import java.math.BigDecimal;
302	import java.math.RoundingMode;
303	
304	public class PricingUtil {
305	    private static final int SCALE = 2;
306	
307	    public static BigDecimal round(BigDecimal value) {
308	        if (value == null) {
309	            return BigDecimal.ZERO;
310	        }
311	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
312	    }
313	
314	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
315	        return round(a.add(b));
316	    }
317	
318	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
319	        return round(a.subtract(b));
320	    }
321	
322	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
323	        return round(a.multiply(b));
324	    }
325	
326	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
327	        return round(a.divide(b, SCALE, RoundingMode.HALF_EVEN));
328	    }
329	
330	    public static BigDecimal percentage(BigDecimal base, BigDecimal percent) {
331	        return round(base.multiply(percent).divide(new BigDecimal("100"), SCALE, RoundingMode.HALF_EVEN));
332	    }
333	
334	    public static int ceilDays(double hours) {
335	        return (int) Math.ceil(hours / 24.0);
336	    }
337	}

