     1	package com.loja.orderservice.service;
     2	
     3	import com.loja.orderservice.dto.OrderItemDTO;
     4	import com.loja.orderservice.dto.OrderRequestDTO;
     5	import com.loja.orderservice.entity.*;
     6	import com.loja.orderservice.exception.OrderException;
     7	import com.loja.orderservice.repository.CustomerRepository;
     8	import com.loja.orderservice.repository.CustomerNotificationRepository;
     9	import com.loja.orderservice.repository.OrderRepository;
    10	import com.loja.orderservice.repository.ProductRepository;
    11	import com.loja.orderservice.util.PricingUtil;
    12	import org.springframework.http.HttpStatus;
    13	import org.springframework.stereotype.Service;
    14	import org.springframework.transaction.annotation.Transactional;
    15	
    16	import java.math.BigDecimal;
    17	import java.time.Instant;
    18	import java.util.ArrayList;
    19	import java.util.List;
    20	import java.util.Optional;
    21	
    22	@Service
    23	public class OrderService {
    24	    private final OrderRepository orderRepository;
    25	    private final ProductRepository productRepository;
    26	    private final CustomerRepository customerRepository;
    27	    private final CustomerNotificationRepository notificationRepository;
    28	    private final PricingService pricingService;
    29	    private final ValidationService validationService;
    30	
    31	    public OrderService(OrderRepository orderRepository, ProductRepository productRepository,
    32	                        CustomerRepository customerRepository, CustomerNotificationRepository notificationRepository,
    33	                        PricingService pricingService, ValidationService validationService) {
    34	        this.orderRepository = orderRepository;
    35	        this.productRepository = productRepository;
    36	        this.customerRepository = customerRepository;
    37	        this.notificationRepository = notificationRepository;
    38	        this.pricingService = pricingService;
    39	        this.validationService = validationService;
    40	    }
    41	
    42	    public OrderSummary calculateSummary(OrderRequestDTO request) {
    43	        validationService.validateOrderRequest(request);
    44	        return pricingService.calculateSummary(request);
    45	    }
    46	
    47	    @Transactional
    48	    public Order createOrder(OrderRequestDTO request) {
    49	        // Validate
    50	        validationService.validateOrderRequest(request);
    51	
    52	        // Calculate summary
    53	        OrderSummary summary = pricingService.calculateSummary(request);
    54	
    55	        // Create order
    56	        Order order = new Order(
    57	            request.getCustomer().getCpf(),
    58	            request.getCustomer().getEmail(),
    59	            request.getZipCode(),
    60	            request.getRegion(),
    61	            request.getShippingMethod(),
    62	            request.getCoupon(),
    63	            request.getPaymentMethod(),
    64	            request.getInstallments() != null ? request.getInstallments() : 1,
    65	            request.getClubTier()
    66	        );
    67	
    68	        order.setSummary(summary);
    69	
    70	        // Add items
    71	        for (OrderItemDTO item : request.getItems()) {
    72	            OrderItem orderItem = new OrderItem(item.getSku(), item.getQuantity());
    73	            order.getItems().add(orderItem);
    74	        }
    75	
    76	        // Save order
    77	        return orderRepository.save(order);
    78	    }
    79	
    80	    public Order getOrder(String orderId) {
    81	        return orderRepository.findById(orderId)
    82	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND));
    83	    }
    84	
    85	    @Transactional
    86	    public Order processPayment(String orderId, String transactionId, Instant paidAt) {
    87	        Order order = getOrder(orderId);
    88	
    89	        // Check if order is awaiting payment
    90	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
    91	            throw new OrderException("OPERATION_NOT_ALLOWED", "Order is not awaiting payment", HttpStatus.CONFLICT);
    92	        }
    93	
    94	        // Check if payment is too late (more than 48 hours)
    95	        Instant createdAt = order.getCreatedAt();
    96	        Instant deadline = createdAt.plusSeconds(48 * 60 * 60);
    97	        if (paidAt.isAfter(deadline)) {
    98	            order.setStatus(OrderStatus.CANCELLED);
    99	            orderRepository.save(order);
   100	            notifyCustomer(order, NotificationType.ORDER_CANCELLED);
   101	            throw new OrderException("ORDER_EXPIRED", "Payment is too late", HttpStatus.CONFLICT);
   102	        }
   103	
   104	        // Check if this is a duplicate payment (same transactionId)
   105	        if (transactionId.equals(order.getLastTransactionId())) {
   106	            // Already processed, return current state
   107	            return order;
   108	        }
   109	
   110	        // Check if there's enough stock
   111	        validateStock(order);
   112	
   113	        // Process payment
   114	        order.setStatus(OrderStatus.PAID);
   115	        order.setPaidAt(paidAt);
   116	        order.setLastTransactionId(transactionId);
   117	
   118	        // Deduct from stock
   119	        deductStock(order);
   120	
   121	        // Add credit to customer
   122	        addCreditToCustomer(order);
   123	
   124	        // Save
   125	        orderRepository.save(order);
   126	
   127	        // Notify customer
   128	        notifyCustomer(order, NotificationType.PAYMENT_APPROVED);
   129	
   130	        return order;
   131	    }
   132	
   133	    @Transactional
   134	    public Order shipOrder(String orderId, String trackingCode) {
   135	        Order order = getOrder(orderId);
   136	
   137	        if (order.getStatus() != OrderStatus.PAID) {
   138	            throw new OrderException("OPERATION_NOT_ALLOWED", "Order is not paid", HttpStatus.CONFLICT);
   139	        }
   140	
   141	        order.setStatus(OrderStatus.SHIPPED);
   142	        order.setTrackingCode(trackingCode);
   143	        orderRepository.save(order);
   144	
   145	        notifyCustomer(order, NotificationType.ORDER_SHIPPED);
   146	
   147	        return order;
   148	    }
   149	
   150	    @Transactional
   151	    public Order deliverOrder(String orderId) {
   152	        Order order = getOrder(orderId);
   153	
   154	        if (order.getStatus() != OrderStatus.SHIPPED) {
   155	            throw new OrderException("OPERATION_NOT_ALLOWED", "Order is not shipped", HttpStatus.CONFLICT);
   156	        }
   157	
   158	        order.setStatus(OrderStatus.DELIVERED);
   159	        orderRepository.save(order);
   160	
   161	        return order;
   162	    }
   163	
   164	    @Transactional
   165	    public Order cancelOrder(String orderId) {
   166	        Order order = getOrder(orderId);
   167	
   168	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
   169	            throw new OrderException("OPERATION_NOT_ALLOWED", "Cannot cancel a shipped or delivered order", HttpStatus.CONFLICT);
   170	        }
   171	
   172	        if (order.getStatus() == OrderStatus.CANCELLED) {
   173	            // Already cancelled, just return
   174	            return order;
   175	        }
   176	
   177	        // If paid, need to restore stock and credit
   178	        if (order.getStatus() == OrderStatus.PAID) {
   179	            restoreStock(order);
   180	            removeCreditFromCustomer(order);
   181	        }
   182	
   183	        order.setStatus(OrderStatus.CANCELLED);
   184	        orderRepository.save(order);
   185	
   186	        notifyCustomer(order, NotificationType.ORDER_CANCELLED);
   187	
   188	        return order;
   189	    }
